host:
harness.define({
  name: "hello-plugin",
  inject: ["tools"],
  apply(ctx, config) {
    const who = config?.name ?? "世界";
    ctx.get("tools").register({
      name: "hello_plugin",
      label: "Hello 插件",
      icon: "👋",
      description: "返回一句问候（模板插件）",
      create: () => ({
        description: "打招呼",
        inputSchema: {},
        execute: async () => `你好，${who}！`,
      }),
    });
  },
});

client:
harness.define({
  name: "hello-plugin-ui",
  apply(ctx) {
    ctx.get("uiSlots").register({
      id: "hello-plugin-button",
      slot: "sidebar.footer.action",
      kind: "list",
      order: 20,
      component: harness.createElement(
        "button",
        {
          type: "button",
          title: "Hello 插件",
          "aria-label": "Hello 插件",
          className: "flex h-7 w-7 items-center justify-center rounded-full text-shell-label-secondary hover:bg-shell-row-hover",
          onClick: () => window.alert("Hello from plugin"),
        },
        "👋",
      ),
    });
  },
});
